                  id: 'micro_q34_1',
                  questionNumber: 1,
                  text: 'According to the Gell and Coombs classification, Type I Hypersensitivity is mediated by IgE antibodies and mast cell degranulation. What is the classic mechanism and example of Type IV (Delayed-type) hypersensitivity?',
                  options: [
                    { id: 'A', text: 'Sensitized T-lymphocyte (Th1 / CD4+ and CD8+) activation with macrophage recruitment; Tuberculin (Mantoux) skin test and contact dermatitis' },
                    { id: 'B', text: 'Immune complex deposition with complement activation; Serum sickness' },
                    { id: 'C', text: 'IgG/IgM antibody binding to fixed cell-surface antigens; Goodpasture syndrome' },
                    { id: 'D', text: 'IgE cross-linking on basophils; Anaphylaxis' }
                  ],
                  correctOption: 'A',
                  explanation: 'Type IV Hypersensitivity is antibody-independent and mediated by sensitized T cells (Th1/Th17) releasing IFN-gamma to activate macrophages (24-72 hours peak onset). Classic examples: Mantoux tuberculin test, Contact dermatitis (poison ivy, nickel), Granulomatous inflammation.',
                  keyConcept: 'Hypersensitivity Types: I = IgE/Anaphylactic, II = Cytotoxic (fixed Ag), III = Immune Complex, IV = T-cell mediated (Delayed/Mantoux).'
