                  keyConcept: 'Ocular Embryology: Surface ectoderm -> Lens & Corneal epithelium; Neural ectoderm -> Retina, RPE, Optic nerve, Iris muscles; Neural crest -> Corneal stroma/endothelium, Sclera, Trabecular meshwork.'
